-- traffic grew 50x: move from daily to hourly partitions
ALTER TABLE lake.sales.orders REPLACE PARTITION FIELD order_ts_day WITH hours(order_ts);

-- add or drop fields
ALTER TABLE lake.sales.orders ADD PARTITION FIELD truncate(2, status);
ALTER TABLE lake.sales.orders DROP PARTITION FIELD truncate(2, status);

SELECT * FROM lake.sales.orders VERSION AS OF 7349811762263001000;
SELECT * FROM lake.sales.orders TIMESTAMP AS OF '2026-11-16 08:00:00';

-- undo a bad load
CALL lake.system.rollback_to_snapshot('sales.orders', 5102938475610293000);

-- named references
ALTER TABLE lake.sales.orders CREATE TAG `eom_2026_10` RETAIN 365 DAYS;
ALTER TABLE lake.sales.orders CREATE BRANCH audit;
SELECT * FROM lake.sales.orders VERSION AS OF 'audit';
